[{}, {}, [1], [1], [0], [1], [2], ['node_id] = (x, y)\n        elif demand_section:\n            parts = line.split()\n            if len(parts) >= 2:\n                node_id = int(parts[0])\n                demand = int(parts[1])\n                demands[node_id] = demand\n    \n    return {\n        \'nodes\': nodes,\n        \'demands\': demands,\n        \'capacity\': capacity,\n        \'dimension\': dimension\n    }\n\ndef parse_sol_file(file_path):\n    "', '\n    Parse a .sol file to extract the optimal objective value (cost/distance).\n    \n    Args:\n        file_path (str): Path to the .sol file\n        \n    Returns:\n        float: Optimal cost\n    "', '\n    with open(file_path, \'r\') as f:\n        lines = f.readlines()\n    \n    for line in lines:\n        if line.startswith(\'Cost\'):\n            return float(line.split()[1])\n    \n    return None\n\ndef calculate_euclidean_distance(node1, node2, nodes):\n    "', '\n    Calculate the Euclidean distance between two nodes.\n    \n    Args:\n        node1 (int): First node ID\n        node2 (int): Second node ID\n        nodes (dict): Dictionary of nodes with coordinates\n        \n    Returns:\n        float: Euclidean distance between the nodes\n    "', '\n    x1, y1 = nodes[node1]\n    x2, y2 = nodes[node2]\n    return math.sqrt((x2 - x1)**2 + (y2 - y1)**2)\n\ndef calculate_total_distance(route, nodes):\n    "', '\n    Calculate the total Euclidean distance of a given route.\n    \n    Args:\n        route (list): List of node IDs in order\n        nodes (dict): Dictionary of nodes with coordinates\n        \n    Returns:\n        float: Total distance of the route\n    "', '\n    if not route:\n        return 0\n    \n    # Add depot (node 1) at the beginning and end\n    full_route = [1] + route + [1]\n    total_distance = 0\n    \n    for i in range(len(full_route) - 1):\n        total_distance += calculate_euclidean_distance(full_route[i], full_route[i+1], nodes)\n    \n    return total_distance\n\ndef clarke_wright_savings(nodes, demands, capacity):\n    "', '\n    Implement the Clarke-Wright Savings algorithm to generate initial routes.\n    \n    Args:\n        nodes (dict): Dictionary of nodes with coordinates\n        demands (dict): Dictionary of node demands\n        capacity (int): Vehicle capacity\n        \n    Returns:\n        list: List of routes (each route is a list of node IDs)\n    "', '\n    depot = 1\n    \n    # Initialize routes with each customer in a separate route\n    routes = []\n    route_demands = {}\n    \n    for node_id in nodes:\n        if node_id != depot:\n            route = [node_id]\n            routes.append(route)\n            route_demands[id(route)] = demands[node_id]\n    \n    # Calculate savings\n    savings = []\n    for i in nodes:\n        if i != depot:\n            for j in nodes:\n                if j != depot and i != j:\n                    # Calculate savings s_ij = c_i0 + c_0j - c_ij\n                    s_ij = (calculate_euclidean_distance(i, depot, nodes) + \n                           calculate_euclidean_distance(depot, j, nodes) - \n                           calculate_euclidean_distance(i, j, nodes))\n                    savings.append((s_ij, i, j))\n    \n    # Sort savings in descending order\n    savings.sort(reverse=True)\n    \n    # Merge routes based on savings\n    for saving, i, j in savings:\n        route_i = None\n        route_j = None\n        route_i_index = None\n        route_j_index = None\n        \n        # Find routes containing nodes i and j\n        for idx, route in enumerate(routes):\n            if i in route and route_i is None:\n                route_i = route\n                route_i_index = idx\n            if j in route and route_j is None:\n                route_j = route\n                route_j_index = idx\n        \n        # Check if routes can be merged\n        if (route_i is not None and route_j is not None and \n            route_i_index != route_j_index and\n            route_demands.get(id(route_i), 0) + route_demands.get(id(route_j), 0) <= capacity):\n            \n            # Merge routes: add route_j to the end of route_i\n            new_route = route_i + route_j\n            new_route_demand = route_demands.get(id(route_i), 0) + route_demands.get(id(route_j), 0)\n            \n            # Remove the old routes\n            # Need to pop in descending order to avoid index issues\n            if route_i_index > route_j_index:\n                routes.pop(route_i_index)\n                routes.pop(route_j_index)\n            else:\n                routes.pop(route_j_index)\n                routes.pop(route_i_index)\n            \n            # Add the new route\n            routes.append(new_route)\n            \n            # Update route demands\n            # Remove old route demands and add new one\n            temp_dict = {}\n            for key, value in route_demands.items():\n                if key not in [id(route_i), id(route_j)]:\n                    temp_dict[key] = value\n            temp_dict[id(new_route)] = new_route_demand\n            route_demands = temp_dict\n    \n    return routes\n\ndef two_opt(route, nodes):\n    "', '\n    Implement the 2-Opt Local Search algorithm to optimize routing order.\n    \n    Args:\n        route (list): List of node IDs in order\n        nodes (dict): Dictionary of nodes with coordinates\n        \n    Returns:\n        list: Optimized route\n    "', '\n    if len(route) < 3:\n        return route\n    \n    best_route = route[:]\n    best_distance = calculate_total_distance(route, nodes)\n    improved = True\n    \n    while improved:\n        improved = False\n        for i in range(1, len(route) - 1):\n            for j in range(i + 1, len(route)):\n                # Create a new route by swapping edges\n                new_route = route[:]\n                new_route[i:j+1] = route[i:j+1][::-1]  # Reverse the segment\n                \n                new_distance = calculate_total_distance(new_route, nodes)\n                \n                if new_distance < best_distance:\n                    best_route = new_route\n                    best_distance = new_distance\n                    route = new_route\n                    improved = True\n    \n    return best_route\n\ndef process_instance(vrp_file, sol_file):\n    "', '\n    Process a single VRP instance: parse data, run algorithms, and collect results.\n    \n    Args:\n        vrp_file (str): Path to the .vrp file\n        sol_file (str): Path to the .sol file\n        \n    Returns:\n        dict: Results for this instance\n    "', '\n    # Parse VRP file\n    vrp_data = parse_vrp_file(vrp_file)\n    nodes = vrp_data[\'nodes\']\n    demands = vrp_data[\'demands\']\n    capacity = vrp_data[\'capacity\']\n    dimension = vrp_data[\'dimension\']\n    \n    # Parse solution file\n    optimal_cost = parse_sol_file(sol_file)\n    \n    # Run Clarke-Wright algorithm\n    start_time = time.time()\n    cw_routes = clarke_wright_savings(nodes, demands, capacity)\n    cw_time = time.time() - start_time\n    \n    # Calculate Clarke-Wright solution cost\n    cw_total_distance = 0\n    for route in cw_routes:\n        cw_total_distance += calculate_total_distance(route, nodes)\n    \n    # Run 2-Opt optimization on each route\n    start_time = time.time()\n    optimized_routes = []\n    for route in cw_routes:\n        if len(route) >= 2:  # Only optimize routes with 2 or more nodes\n            optimized_route = two_opt(route, nodes)\n            optimized_routes.append(optimized_route)\n        else:\n            optimized_routes.append(route)\n    \n    two_opt_time = time.time() - start_time\n    \n    # Calculate 2-Opt solution cost\n    two_opt_total_distance = 0\n    for route in optimized_routes:\n        two_opt_total_distance += calculate_total_distance(route, nodes)\n    \n    # Calculate optimality gaps\n    cw_gap = ((cw_total_distance - optimal_cost) / optimal_cost) * 100 if optimal_cost and optimal_cost > 0 else 0\n    two_opt_gap = ((two_opt_total_distance - optimal_cost) / optimal_cost) * 100 if optimal_cost and optimal_cost > 0 else 0\n    \n    # Extract instance name from file name\n    instance_name = os.path.basename(vrp_file).replace(\'.vrp\', \'\')\n    \n    return {\n        \'Instance Name\': instance_name,\n        \'Optimal Cost\': optimal_cost,\n        \'CW Cost\': round(cw_total_distance, 2),\n        \'CW Gap %\': round(cw_gap, 2),\n        \'CW Time\': round(cw_time, 4),\n        \'2-Opt Cost\': round(two_opt_total_distance, 2),\n        \'2-Opt Gap %\': round(two_opt_gap, 2),\n        \'Total Time\': round(cw_time + two_opt_time, 4)\n    }\n\ndef benchmark_directory(data_directory):\n    "', '\n    Run the benchmarking pipeline on all .vrp/.sol pairs in a directory.\n    \n    Args:\n        data_directory (str): Path to the directory containing .vrp and .sol files\n        \n    Returns:\n        pandas.DataFrame: Results of the benchmarking\n    "', '\n    results = []\n    \n    # Get all .vrp files in the directory\n    vrp_files = [f for f in os.listdir(data_directory) if f.endswith(\'.vrp\')]\n    \n    for vrp_file in vrp_files:\n        # Find corresponding .sol file\n        sol_file = vrp_file.replace(\'.vrp\', \'.sol\')\n        vrp_path = os.path.join(data_directory, vrp_file)\n        sol_path = os.path.join(data_directory, sol_file)\n        \n        # Check if both files exist\n        if os.path.exists(vrp_path) and os.path.exists(sol_path):\n            try:\n                print(f"Processing {vrp_file}...', 'result = process_instance(vrp_path, sol_path)\n                results.append(result)\n            except Exception as e:\n                print(f"Error processing {vrp_file}: {str(e)}")\n        else:\n            print(f"Missing pair for {vrp_file}")\n    \n    # Create DataFrame and sort by instance name\n    df = pd.DataFrame(results)\n    if not df.empty:\n        df = df.sort_values(\'Instance Name\').reset_index(drop=True)\n    \n    return df\n\ndef main(data_directory):\n    "', '\n    Main execution function that runs the benchmarking pipeline.\n    \n    Args:\n        data_directory (str): Path to the directory containing .vrp and .sol files\n    "', '\n    print("Starting VRP benchmarking...")\n    \n    # Run benchmarking\n    results_df = benchmark_directory(data_directory)\n    \n    if results_df.empty:\n        print("No results to display.")\n        return\n    \n    # Print formatted summary\n    print("\nBenchmarking Results:")\n    print("=', 100, 'print(results_df.to_string(index=False))\n    \n    # Export to CSV\n    results_df.to_csv(\'benchmark_results.csv\', index=False)\n    print("\nResults exported to \'benchmark_results.csv\'")\n    \n    # Print summary statistics\n    print("\nSummary Statistics:")\n    print("=" * 50)\n    print(f"Total instances processed: {len(results_df)}")\n    if not results_df.empty:\n        print(f', 'Average CW Gap %: {results_df[\'CW Gap %\'].mean():.2f}%")\n        print(f', 'Average 2-Opt Gap %: {results_df[\'2-Opt Gap %\'].mean():.2f}%")\n        print(f', 'Average CW Time (s): {results_df[\'CW Time\'].mean():.4f}")\n        print(f', 'Average Total Time (s): {results_df[\'Total Time\'].mean():.4f}")\n\nif __name__ == "__main__":\n    # Run the benchmarking on the data directory\n    data_dir = "./data', 'Change this to your data directory\n    main(data_dir)']]